<template><strategy-dialog title="Calculateur de dégâts" @close="$emit('close')">
 <p class="calc-lead">Compare deux compagnons de ton équipe avec les règles réelles de l’Aventure. Cette simulation ne modifie ni leurs PV, ni leurs PP, ni leurs objets.</p>
 <div v-if="usable.length<2" class="calc-empty">Il te faut deux Pokémon dans l’équipe pour comparer leurs dégâts.</div>
 <template v-else>
 <div class="calc-matchup"><article v-for="side in sides" :key="side.key" class="calc-pokemon" :class="side.key"><label :for="'calc-'+side.key">{{ side.label }}</label><select :id="'calc-'+side.key" v-model="selection[side.key]" @change="resetMove(side.key)"><option v-for="p in usable" :key="p.uuid" :value="p.uuid">{{ p.name }} · N. {{ p.level }}</option></select><template v-if="combatant(side.key)"><div class="calc-art"><pokemon-portrait :src="$pokemonSprite(combatant(side.key),{side:side.key==='attacker'?'back':'front',animated:true})" :alt="combatant(side.key).name"/></div><h3>{{ combatant(side.key).name }} <potential-star :value="combatant(side.key).k"/></h3><div class="calc-types"><span v-for="t in currentTypes(combatant(side.key))" :key="t" :style="typeStyle(t)">{{ typeName(t) }}</span></div><p>N. {{ combatant(side.key).level }} · {{ combatant(side.key).maxHp }} PV</p><small>{{ abilityName(combatant(side.key).passiveAbility) }}<template v-if="combatant(side.key).heldItem"> · {{ combatant(side.key).heldItemName || combatant(side.key).heldItem }}</template></small></template></article><button class="calc-swap" @click="swap" aria-label="Inverser l’attaquant et le défenseur">⇄</button></div>
 <h3 class="calc-section-title">Choisis une capacité</h3><div class="calc-moves"><button v-for="(m,i) in moves" :key="m.name" :aria-pressed="moveIndex===i" :style="typeStyle(m.type)" @click="moveIndex=i" :data-calculator-move="i"><strong>{{ moveName(m.name) }}</strong><small>{{ typeName(m.type) }} · {{ m.damageClass==='physical'?'Physique':m.damageClass==='special'?'Spéciale':'Statut' }}</small><span>Puissance {{ m.powerLabel }} · {{ m.accuracy>0?m.accuracy+' %':'Toujours' }}</span></button></div><p v-if="moves[moveIndex]" class="calc-description">{{ moves[moveIndex].description }}</p>
 <div class="calc-status" role="status"><span v-if="busy">Calcul en cours…</span><span v-else-if="error" class="calc-error">{{ error }}</span><span v-else>Simulation sur les Pokémon de ton équipe · sans coup adverse</span></div>
 <section v-if="result&&!busy" class="calc-result" data-calculator-result><div><small>DÉGÂTS SUR LES PV</small><strong>{{ result.min }}<template v-if="result.max!==result.min"> – {{ result.max }}</template> <em>PV</em></strong><span>{{ number(result.minPercent) }}<template v-if="result.maxPercent!==result.minPercent"> – {{ number(result.maxPercent) }}</template> % des PV max.</span></div><div class="calc-verdict"><b>{{ result.effectiveness===0?'Immunité':result.effectiveness>1?'Super efficace':result.effectiveness<1?'Peu efficace':'Efficacité neutre' }} · ×{{ number(result.effectiveness) }}</b><span :class="{'is-ko':result.possibleKo}">{{ result.guaranteedKo?'K.O. garanti si la capacité touche':result.possibleKo?'K.O. possible':'Pas de K.O. en un coup' }}</span><small v-if="result.hits[1]>1">{{ result.hits[0] }}<template v-if="result.hits[0]!==result.hits[1]"> à {{ result.hits[1] }}</template> impacts</small></div><div class="calc-health" role="img" :aria-label="'PV restants : '+result.minHpAfter+' à '+result.maxHpAfter"><i :style="{width:result.maxHpAfter/result.defenderMaxHp*100+'%'}"/><b :style="{left:result.minHpAfter/result.defenderMaxHp*100+'%',width:(result.maxHpAfter-result.minHpAfter)/result.defenderMaxHp*100+'%'}"/></div><p class="calc-hp-label">PV après l’attaque : {{ result.minHpAfter }}<template v-if="result.maxHpAfter!==result.minHpAfter"> – {{ result.maxHpAfter }}</template> / {{ result.defenderMaxHp }}</p></section>
 <details class="calc-context"><summary>Conditions de simulation <span>Niveau, météo, PV et statistiques</span></summary><div class="calc-common-level"><label for="calc-common-level">Niveau commun</label><select id="calc-common-level" v-model.number="options.commonLevel" data-calc-level><option :value="0">Niveaux actuels</option><option v-for="n in [25,50,75,100,150,200,250,300]" :key="n" :value="n">Niveau {{ n }}</option><option :value="-1">Personnalisé…</option></select><input v-if="options.commonLevel===-1" type="number" min="1" max="9999" v-model.number="customLevel" placeholder="Niveau" aria-label="Niveau commun personnalisé"/><small>Seulement pour la simulation. IV, EV, K, talent et objet conservés.</small></div><div class="calc-context-grid"><label>Météo<select v-model="options.weather"><option value="">Aucune</option><option value="rain">Pluie</option><option value="sun">Soleil</option><option value="sandstorm">Tempête de sable</option><option value="hail">Grêle / neige</option></select></label><label>Terrain<select v-model="options.terrain"><option value="">Aucun</option><option value="electric_terrain">Électrifié</option><option value="grassy_terrain">Herbu</option><option value="psychic_terrain">Psychique</option><option value="misty_terrain">Brumeux</option></select></label><template v-for="s in sides"><label :key="s.key+'hp'">PV · {{ s.label }}<input v-if="simulationLevel" type="number" min="0" max="100" v-model.number="options[s.key+'HpPercent']" :aria-label="'PV en pourcentage · '+s.label"/><input v-else type="number" min="0" :max="combatant(s.key)?.maxHp" v-model.number="options[s.key+'Hp']"/><small v-if="simulationLevel">% des PV maximum au niveau simulé</small></label><label :key="s.key+'status'">Statut · {{ s.label }}<select v-model="options[s.key+'Status']"><option v-for="s in statuses" :key="s[0]" :value="s[0]">{{ s[1] }}</option></select></label></template></div><div class="calc-context-grid"><label>Dégâts reçus par le lanceur ce tour<input type="number" min="0" :max="attacker?.maxHp" v-model.number="options.incomingDamage"/></label><label>Nature de ces dégâts<select v-model="options.incomingSpecial"><option :value="false">Physiques</option><option :value="true">Spéciaux</option></select></label></div><div class="calc-checks"><label><input type="checkbox" v-model="options.critical"/> Coup critique</label><label><input type="checkbox" v-model="options.firstAction"/> Première action du lanceur</label><label><input type="checkbox" v-model="options.opponentAttacks"/> L’adversaire prépare une attaque</label><label><input type="checkbox" v-model="options.movedLast"/> L’adversaire a déjà agi</label><label><input type="checkbox" v-model="options.defenderHurt"/> Cible déjà blessée ce tour</label><label><input type="checkbox" v-model="options.reflect"/> Protection adverse</label><label><input type="checkbox" v-model="options.lightScreen"/> Mur Lumière adverse</label></div><div class="calc-boosts"><span>Variations de stats</span><b>Attaquant</b><b>Défenseur</b><template v-for="stat in stats"><label :key="stat.key">{{ stat.label }}</label><select v-for="s in sides" :key="stat.key+s.key" v-model.number="options[s.key+'Boosts'][stat.key]" :aria-label="stat.label+' '+s.label"><option v-for="n in 13" :key="n" :value="n-7">{{ n-7>0?'+':'' }}{{ n-7 }}</option></select></template></div></details>
 <section v-if="result?.simulated?.level" class="calc-stats-summary" data-calculator-simulated><strong>Comparaison au niveau {{ result.simulated.level }}</strong><p v-for="side in sides" :key="side.key"><b>{{ combatant(side.key).name }}</b><span>{{ result.simulated[side.key].maxHp }} PV</span><span v-for="stat in stats" :key="stat.key">{{ stat.label }} {{ result.simulated[side.key][stat.key] }}</span></p></section>
 <div class="calc-notes"><p v-for="note in result?.notes||[]" :key="note">{{ note }}</p></div>
 </template>
</strategy-dialog></template>
<script>
import StrategyDialog from './StrategyDialog.vue';import PokemonPortrait from '../PokemonPortrait.vue';import PotentialStar from '../PotentialStar.vue';
import{createPokemonReference}from'@/services/pokemonReference';import referenceData from '@/data/pokemonReference.fr.json';import{currentTypes}from'@/services/teamCoverage';import{typeBadgeStyle,localizeTypeName}from'@/services/pokemonTypes';import{localizeMoveName,localizeAbilityName}from'@/services/i18n';
const reference=createPokemonReference(referenceData),stats=[{key:'attack',label:'Attaque'},{key:'defense',label:'Défense'},{key:'specialAttack',label:'Attaque Spé.'},{key:'specialDefense',label:'Défense Spé.'},{key:'speed',label:'Vitesse'}];
export default{components:{StrategyDialog,PokemonPortrait,PotentialStar},props:{team:Array,command:Function},data:()=>({selection:{attacker:'',defender:''},moveIndex:0,customLevel:null,result:null,error:'',busy:false,sides:[{key:'attacker',label:'Attaquant'},{key:'defender',label:'Défenseur'}],stats,statuses:[['normal','Aucun'],['burn','Brûlure'],['poison','Poison'],['badly_poison','Poison grave'],['paralyze','Paralysie'],['sleep','Sommeil'],['freeze','Gel']],options:{commonLevel:0,attackerHpPercent:100,defenderHpPercent:100,weather:'',terrain:'',critical:false,firstAction:true,opponentAttacks:true,movedLast:false,reflect:false,lightScreen:false,incomingDamage:0,incomingSpecial:false,defenderHurt:false,attackerHp:0,defenderHp:0,attackerStatus:'normal',defenderStatus:'normal',attackerBoosts:Object.fromEntries(stats.map(s=>[s.key,0])),defenderBoosts:Object.fromEntries(stats.map(s=>[s.key,0]))}}),computed:{simulationLevel(){return this.options.commonLevel===-1?this.customLevel:this.options.commonLevel;},usable(){return this.team.filter(p=>!p.isEgg);},attacker(){return this.combatant('attacker');},defender(){return this.combatant('defender');},moves(){return this.attacker?reference.moves(this.attacker):[];},signature(){return JSON.stringify([this.team,this.selection,this.moveIndex,this.options,this.customLevel]);}},watch:{signature(){this.schedule();},team:{deep:true,handler(){this.synchronize();}}},mounted(){this.synchronize();this.schedule();},beforeDestroy(){clearTimeout(this._timer);this._sequence=(this._sequence||0)+1;},methods:{currentTypes,typeStyle:typeBadgeStyle,typeName:localizeTypeName,moveName:n=>localizeMoveName(n,'fr'),abilityName:n=>localizeAbilityName(n,'fr'),number:n=>Number(n.toFixed(1)).toLocaleString('fr-FR'),combatant(key){return this.usable.find(p=>p.uuid===this.selection[key]);},synchronize(){for(const s of this.sides){if(!this.combatant(s.key)){this.selection[s.key]=this.usable[s.key==='attacker'?0:1]?.uuid||'';this.resetMove(s.key);}}},resetMove(key){const p=this.combatant(key);if(p){this.options[key+'Hp']=p.currentHp;this.options[key+'HpPercent']=Math.round(p.currentHp/p.maxHp*100);this.options[key+'Status']=p.status||'normal';}if(key==='attacker')this.moveIndex=0;},swap(){[this.selection.attacker,this.selection.defender]=[this.selection.defender,this.selection.attacker];this.resetMove('attacker');this.resetMove('defender');},schedule(){clearTimeout(this._timer);this.result=null;this.error='';this._sequence=(this._sequence||0)+1;this._timer=setTimeout(()=>this.calculate(this._sequence),260);},async calculate(sequence){if(this.usable.length<2)return;if(!this.attacker||!this.defender||this.attacker.uuid===this.defender.uuid){this.error='Choisis deux Pokémon différents.';this.busy=false;return;}this.busy=true;try{if(this.options.commonLevel===-1&&(!Number.isInteger(this.customLevel)||this.customLevel<1||this.customLevel>9999))throw Error('Choisis un niveau entre 1 et 9 999.');const r=await this.command({attacker:this.attacker.uuid,defender:this.defender.uuid,move:this.moveIndex,options:{...JSON.parse(JSON.stringify(this.options)),commonLevel:this.simulationLevel??-1}});if(sequence===this._sequence)this.result=r;}catch(e){if(sequence===this._sequence)this.error=e.message;}finally{if(sequence===this._sequence)this.busy=false;}}}};
</script>
